def min_absolute_difference(nums: List[int], k: int) -> int:
    ans = 10**30
    prev_or = 0

    for x in nums:
        cur_or = prev_or | x

        diff = abs(k - cur_or)
        if diff < ans:
            ans = diff
            if ans == 0:
                return 0

    return ans
