def count_beautiful_numbers(l: int, r: int) -> int:
    if l > r:
        return 0
    return _count_up_to(r) - _count_up_to(l - 1)

def _count_up_to(n:
    if n < 1:
        return 0
    digits = str(n)
    dp, need, s_max = _tables(len(digits))
    state = 0
    total = 0
    for pos, ch in enumerate(digits):
        limit = ord(ch) - 48
        nxt = dp[pos + 1]
        for d in range(limit):
            nst = _transition(state, d, s_max)
            if nst >= 0:
                v = nxt.get(nst)
                if v:
                    total += v
        state = _transition(state, limit, s_max)
    return total + _is_beautiful_state(state, need)

def _tables(num_digits:
    s_max = 9 * num_digits
    need = [(0, 0, 0, 0, False)] + [_factor_exp(s) for s in range(1, s_max + 1)]
    states = [set() for _ in range(num_digits + 1)]
    states[0].add(0)
    for pos in range(num_digits):
        nxt = states[pos + 1]
        for st in states[pos]:
            for d in range(10):
                nst = _transition(st, d, s_max)
                if nst >= 0:
                    nxt.add(nst)
    dp = [None] * (num_digits + 1)
    dp[num_digits] = {st: _is_beautiful_state(st, need) for st in states[num_digits]}
    for pos in range(num_digits - 1, -1, -1):
        nxt = dp[pos + 1]
        get = nxt.get
        cur = {}
        for st in states[pos]:
            total = 0
            for d in range(10):
                nst = _transition(st, d, s_max)
                if nst >= 0:
                    v = get(nst)
                    if v:
                        total += v
            cur[st] = total
        dp[pos] = cur
    return dp, need, s_max

def _factor_exp(n:
    a, b, c, d, rest_is_one = n == 1
    while n % 2 == 0:
        n //= 2
        a += 1
    while n % 3 == 0:
        n //= 3
        b += 1
    while n % 5 == 0:
        n //= 5
        c += 1
    while n % 7 == 0:
        n //= 7
        d += 1
    return a, b, c, d, rest_is_one

def _transition(state, d, s_max):
    started = (state >> 10) & 1
    s = state >> 11
    if started:
        ns = s + d
        if ns > s_max:
            return -1
        if d == 0 or (state >> 9) & 1:
            return (ns << 11) | (1 << 10) | (1 << 9)
        return ((ns << 11) | (1 << 10) | _NCODE[(state & 511) * 9 + d - 1])
    if d == 0:
        return 0
    return (d << 11) | (1 << 10) | _NCODE[d - 1]

_STATE_BITS = 11

_DIG_EXP = []
for _d in range(10):
    _v = [0, 0, 0, 0]
    for _i, _p in enumerate((2, 3, 5, 7)):
        _dd, _e = _d, 0
        while _dd and _dd % _p == 0:
            _dd //= _p
            _e += 1
        _v[_i] = _e
    _DIG_EXP.append(_v)

_NCODE = [0] * (315 * 9)
for _code in range(315):
    _e2, _e3, _e5, _e7 = _decode(_code)
    for _d in range(1, 10):
        _v = _DIG_EXP[_d]
        _NCODE[_code * 9 + _d - 1] = _encode(
            min(_e2 + _v[0], 6),
            min(_e3 + _v[1], 4),
            min(_e5 + _v[2], 2),
            min(_e7 + _v[3], 2),
        )

def _decode(code):
    e2, rem = divmod(code, 45)
    e3, rem = divmod(rem, 9)
    e5, e7 = divmod(rem, 3)
    return e2, e3, e5, e7

def _is_beautiful_state(state, need):
    if not (state >> 10) & 1:
        return 0
    if (state >> 9) & 1:
        return 1
    a, b, c, d, only_small_primes = need[state >> 11]
    if not only_small_primes:
        return 0
    e2, e3, e5, e7 = _decode(state & 511)
    return 1 if (e2 >= a and e3 >= b and e5 >= c and e7 >= d) else 0
