import math

def is_beautiful(num):
    digits = [int(d) for d in str(num)]
    product = math.prod(digits)
    if product == 0:
        return True
    return product % sum(digits) == 0

def count_beautiful_numbers(l: int, r: int) -> int:
    return sum(is_beautiful(num) for num in range(l, r + 1))
