def paint_walls(cost: List[int], time: List[int]) -> int:
    n = len(cost)
    dp = [float("inf")] * (n + 1)
    dp[0] = 0

    for i in range(n):
        c, t = cost[i], time[i] + 1
        for j in range(n, 0, -1):
            if j - t >= 0:
                dp[j] = min(dp[j], dp[j - t] + c)
    return dp[n]
