def count_good_arrays(n: int, m: int, k: int) -> int:
    MOD = 10**9 + 7
    if k < 0 or k > n - 1:
        return 0

    # Base case: only one element
    if n == 1:
        return m % MOD

    # If k is 0, we have m choices for the first element and (m-1)^(n-1) for the rest
    if k == 0:
        return (m * pow(m - 1, n - 1, MOD)) % MOD

    # General case: choose k gaps from n-1 to be equal, and then arrange the values
    return _comb_mod(n - 1, k) * (m * pow(m - 1, n - 1 - k, MOD)) % MOD


def _comb_mod(n: int, k: int) -> int:
    if k < 0 or k > n:
        return 0
    fact = [1] * (n + 1)
    invfact = [1] * (n + 1)

    for i in range(2, n + 1):
        fact[i] = fact[i - 1] * i % MOD
        invfact[i] = pow(fact[i], MOD - 2, MOD)

    return fact[n] * invfact[k] * invfact[n - k] % MOD
