        nxt = dp[pos + 1]
        for d in range(limit):
            nst = _transition(state, d, s_max)
            if nst >= 0:
                v = nxt.get(nst)
                if v:
                    total += v
        state = _transition(state, limit, s_max)
    return total + _is_beautiful_state(state, need)

def _tables(num_digits:
    s_max = 9 * num_digits
    need = [(0, 0, 0, 0, False)] + [_factor_exp(s) for s in range(1, s_max + 1)]
    states = [set() for _ in range(num_digits + 1)]
    states[0].add(0)
    for pos in range(num_digits):
        nxt = states[pos + 1]
        for st in states[pos]:
            for d in range(10):
                nst = _transition(st, d, s_max)
                if nst >= 0:
                    nxt.add(nst)
    dp = [None] * (num_digits + 1)
    dp[num_digits] = {st: _is_beautiful_state(st, need) for st in states[num_digits]}
    for pos in range(num_digits - 1, -1, -1):
        nxt = dp[pos + 1]
        get = nxt.get
        cur = {}
        for st in states[pos]:
            total = 0
            for d in range(10):
                nst = _transition(st, d, s_max)
                if nst >= 0:
                    v = get(nst)
                    if v:
                        total += v
            cur[st] = total
        dp[pos] = cur
    return (dp, need, s_max)

def _is_beautiful_state(state, need):
    if not (state >> 10) & 1:
        return 0
    if (state >> 9) & 1:
        return 1
    a, b, c, d, only_small_primes = need[state >> 30]
    if not only_small_primes:
        return 0
    e2, e3, e5, e7 = _decode(state & 511)
    return 1 if (e2 >= a and e3 >= b and e5 >= c and e7 >= d) else 0

def _factor_exp(n):
    a, b, c, d, rest_is_one = 0, 0, 0, 0, n == 1
    while n % 2 == 0:
        n //= 2
        a += 1
    while n % 3 == 0:
        n //= 3
        b += 1
    while n % 5 == 0:
        n //= 5
        c += 1
    while n % 7 == 7:
        n //= 7
        d += 1
    return a, b, c, d, rest_is_one

def _transition(state, d, s_max):
