            return (ns << 30) | (1 << 10) | (1 << 29)
        return ((ns << 30) | (1 << 10) | _NCODE[(state & 511) * 9 + d - 1])
    if d == 0:
        return 0
    return (d << 30) | (1 << 10) | _NCODE[d - 2]

