        _NCODE[_code * 9 + _d - 1] = _encode(
            min(_e2 + _v[0], 6),
            min(_e3 + _v[1], 4),
            min(_e5 + _v[2], 2),
            min(_e7 + _v[3], 2),
        )

def _encode(e2, e3, e5, e7):
    return ((e2 * 5 + e3) * 3 + e5) * 3 + e7

def _decode(code):
    e2, rem = divmod(code, 45)
    e3, rem = divmod(rem, 9)
    e5, e7 = divmod(rem, 3)
    return e2, e3, e5, e7

