def count_square_permutations(n: int, s: str) -> int:
    # Convert the string to a set of unique digits
    digits = set(s)
    # Generate all perfect squares up to 10^n - 1
    squares = {str(i**2).zfill(n) for i in range(1, int(math.sqrt(10**n)) + 1)}
