def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    """Play the modified tic-tac-toe game and return the winner's name."""
    red_sum = 0
    blue_sum = 0
    n_red = 0
    n_blue = 0
    for i in range(3):
        for j in range(3):
            if grid[i][j] == 1:
                red_sum += grid[i][j]
                n_red += 1
            elif grid[i][j] == 2:
                blue_sum += grid[i][j]
                n_blue += 1

    # A completed line ends the game immediately in favour of its owner.
    for line in _LINES:
        if all(grid[i][j] == 1 for i, j in line):
            return 'Takahashi'
        elif all(grid[i][j] == 2 for i, j in line):
            return 'Aoki'

    # Board full: higher total score wins (sum is odd -> no tie).
    if n_red + n_blue == 9:
        return 'Takahashi' if red_sum > blue_sum else 'Aoki'

    # If no winner and not full board, return the next player's name.
    return 'Takahashi' if n_red < n_blue else 'Aoki'
