def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    visited = [copy.deepcopy(grid) for _ in range(H)]
    target = K + 1
    ans = 0

    def dfs(r: int, c: int, depth: int) -> None:
        nonlocal ans

        if depth == target:
            ans += 1
            return

        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if (
                0 <= nr < H
                and 0 <= nc < W
                and grid[nr][nc] == '.'
                and visited[nr][nc] == '.'
            ):
                visited[nr][nc] = '#'
                dfs(nr, nc, depth + 1)
                visited[nr][nc] = '.'

    for r in range(H):
        for c in range(W):
            if grid[r][c] == '.':
                visited[r][c] = '#'
                dfs(r, c, 1)
                visited[r][c] = '.'

    return ans
