def sum_of_subarray_powers(n: int, k: int, a: List[int]) -> int:
    comb = [1] * (k + 1)
    for j in range(1, k + 1):
        comb[j] = comb[j - 1] * (k - j + 1) // j

    cnt = [0] * (k + 1)
    cnt[0] = 1

    ans = 0
    pref = 0

    for x in a:
        pref += x
        if pref >= MOD:
            pref -= MOD

        pow_pref = [1] * (k + 1)
        for j in range(1, k + 1):
            pow_pref[j] = pow_pref[j - 1] * pref % MOD

        term = 0
        for j in range(k + 1):
            coeff = pow_pref[k - j] * cnt[j] % MOD
            coeff = coeff * comb[j] % MOD
            if j & 1:
                term -= coeff
            else:
                term += coeff

        ans = (ans + term) % MOD

        cnt[0] += 1
        if cnt[0] >= MOD:
            cnt[0] -= MOD

        for j in range(1, k + 1):
            cnt[j] += pow_pref[j]
            if cnt[j] >= MOD:
                cnt[j] -= MOD

    return ans
