def sum_imbalance_numbers(nums: List[int]) -> int:
    total = 0
    seen = set()
    runs = 0

    for i in range(len(nums)):
        x = nums[i]
        if x not in seen:
            runs += 1
        seen.add(x)
        for j in range(i+1, len(nums)):
            if nums[j] - nums[i] > 1:
                total += runs - 1
