from typing import List
from functools import lru_cache

_LINES = ((0, 1, 2), (3, 4, 5), (6, 7, 8), (0, 3, 6), (1, 4, 7), (2, 5, 8), (0, 4, 8), (2, 4, 6))

def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    def takahashi_wins(state: tuple) -> bool:
        red_sum, blue_sum = 0, 0
        for i, c in enumerate(state):
            if c == 1:
                red_sum += grid[i // 3][i % 3]
            elif c == 2:
                blue_sum += grid[i // 3][i % 3]

        for a, b, c in _LINES:
            if state[a] != 0 and state[a] == state[b] == state[c]:
                return state[a] == 1

        if not any(state):
            return red_sum > blue_sum
        if state.count(1) == state.count(2):
            return any(takahashi_wins(state[:i] + (1,) + state[i + 1:]) for i in range(9) if state[i] == 0)
        return not any(takahashi_wins(state[:i] + (2,) + state[i + 1:]) for i in range(9) if state[i] == 0)

    return 'Takahashi' if takahashi_wins((0,) * 9) else 'Aoki'
