def can_transform_string(n: int, x: int, y: int, s: str, t: str) -> bool:
    if s == t:
        return True
    if x + y > n:
        return False
    if s.count('1') != t.count('1'):
        return False
    for p, q in zip((i for i, c in enumerate(s) if c == '0'), (i for i, c in enumerate(t) if c == '0')):
        if (p - q) % y:
            return False
    for p, q in zip((i for i, c in enumerate(s) if c == '1'), (i for i, c in enumerate(t) if c == '1')):
        if (p - q) % x:
            return False
    return True
