def count_good_arrays(n: int, m: int, k: int) -> int:
    MOD = 10**9 + 7
    if k < 0 or k > n - 1:
        return 0
    return (m * pow(m - 1, n - 1 - k, MOD) * _comb_mod(n - 1, k)) % MOD

def _comb_mod(n: int, k: int) -> int:
    if k < 0 or k > n:
        return 0
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    return fact[n] * pow(fact[k], MOD - 2, MOD) * pow(fact[n - k], MOD - 2, MOD) % MOD
