from functools import lru_cache

_LINES = (
    (0, 1, 2), (3, 4, 5), (6, 7, 8),
    (0, 3, 6), (1, 4, 7), (2, 5, 8),
    (0, 4, 8), (2, 4, 6),
)

@lru_cache(maxsize=None)
def takahashi_wins(state: tuple) -> bool:
    red_sum = 0
    blue_sum = 0
    n_red = 0
    n_blue = 0
    whites = []
    for i, c in enumerate(state):
        if c == 1:
            red_sum += vals[i]
            n_red += 1
        elif c == 2:
            blue_sum += vals[i]
            n_blue += 1
        else:
            whites.append(i)
    for a, b, c in _LINES:
        if state[a] != 0 and state[a] == state[b] == state[c]:
            return state[a] == 1
    if not whites:
        return red_sum > blue_sum
    if n_red == n_blue:
        for m in whites:
            child = state[:m] + (1,) + state[m + 1:]
            if not takahashi_wins(child):
                return False
        return True
    else:
        for m in whites:
            child = state[:m] + (2,) + state[m + 1:]
            if takahashi_wins(child):
                return True
        return False

