MOD = 998244353

@lru_cache(None)
def stirling2(n, k):
    if n == k == 0:
        return 1
    if n == 0 or k == 0:
        return 0
    return k * stirling2(n - 1, k) + stirling2(n - 1, k - 1)

@lru_cache(None)
def surj(n, k):
    if n < k:
        return 0
    if n == k:
        return math.factorial(k)
    return surj(n - 1, k) * k + surj(n - 1, k - 1)

@lru_cache(None)
def h(c, x, k):
    if c == 0:
        return 1
    return (k - 2) * h(c - 1, x, k) + surj(c - 1, k)

@lru_cache(None)
def g(m, n, x, k):
    if m == 1:
        return surj(n, k)
    if m > n:
        return 0
    h_c = h(x[1], x[0], k)
    return sum(g(m - 1, t, x, k) * h(c, x[0], k) for t in range(n - m + 1) for c in range(n - t - m + 1))

def count_sequences_without_subsequence(N, M, K, X):
    if M > N or M < 1 or K < 2 or len(X) != M:
        return 0
