from typing import List

def max_score(grid: List[List[int]]) -> int:
    rows = len(grid)
    row_values = [set(row) for row in grid]
    columns = [set() for _ in range(len(grid[0]))]
    for r in range(rows):
        for c in range(len(grid[0])):
            columns[c].add(grid[r][c])
    values = sorted({x for row in grid for x in row})
    rows_with_value = {v: [] for v in values}
    for r, row in enumerate(row_values):
        for v in row:
            rows_with_value[v].append(r)
    for c in range(len(grid[0])):
        for v in columns[c]:
            rows_with_value[v].append(c)
    bits = [1 << i for i in range(rows)]
    dp = [-1] * (1 << rows)
    dp[0] = 0
    for v in values:
        ndp = dp[:]
        for mask, cur in enumerate(dp):
            if cur < 0:
                continue
            for r in rows_with_value[v]:
                bit = bits[r]
                if mask & bit:
                    continue
                nmask = mask | bit
                cand = cur + v
                if cand > ndp[nmask]:
                    ndp[nmask] = cand
        dp = ndp
    return max(dp)
