def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    visited = [[False] * W for _ in range(H)]
    target = K + 1
    ans = 0

    def dfs(r: int, c: int, depth: int) -> None:
        nonlocal ans

        if depth == target:
            ans += 1
            return

        for dr, dc in itertools.product(range(-1, 2), repeat=2):
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if (
                0 <= nr < H
                and 0 <= nc < W
                and grid[nr][nc] == '.'
                and not visited[nr][nc]
            ):
                visited[nr][nc] = True
                dfs(nr, nc, depth + 1)
                visited[nr][nc] = False

    for r in range(H):
        for c in range(W):
            if grid[r][c] == '.':
                visited[r][c] = True
                dfs(r, c, 1)
                visited[r][c] = False

    return ans
