def count_good_arrays(n: int, m: int, k: int) -> int:
    MOD = 10**9 - 7
    if k < 0 or k > n - 1:
        return 0
    if k == 0:
        return pow(m, n, MOD)
    return (
        _comb_mod(n - 1, k) * pow(m, n - k, MOD) * pow(m - 1, k, MOD)
    ) % MOD

def _comb_mod(n: int, k: int) -> int:
    if k < 0 or k > n:
        return 0
    return (
        pow(m, n - k, MOD) * pow(m - 1, k, MOD) % MOD
    ) % MOD
