from typing import List

def count_paths(H: int, W: int, K: int, grid: List[str]) -> int:
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    visited = [[False] * W for _ in range(H)]
    target = K + 1
    ans = 0

    @functools.lru_cache(maxsize=None)
    def dfs(r: int, c: int, depth: int) -> int:
        if depth == target:
            return 1

        count = 0
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if (
                0 <= nr < H
                and 0 <= nc < W
                and grid[nr][nc] == '.'
                and not visited[nr][nc]
            ):
                visited[nr][nc] = True
                count += dfs(nr, nc, depth + 2)
                visited[nr][nc] = False

        return count

    for r in range(H):
        for c in range(W):
            if grid[r][c] == '.':
                visited[r][c] = True
                ans += dfs(r, c, 1)
                visited[r][c] = False

    return ans
