def sum_of_subarray_powers(n: int, k: int, a: List[int]) -> int:
    MOD = 998244353
    cnt = [0] * (k + 1)
    pref = 0
    ans = 0
    for x in a:
        pref += x
        if pref >= MOD:
            pref -= MOD
        cnt[0] += 1
        if cnt[0] >= MOD:
            cnt[0] -= MOD
        for j in range(1, k + 1):
            cnt[j] += pref
            if cnt[j] >= MOD:
                cnt[j] -= MOD
        term = 0
        for j in range(k + 1):
            term += cnt[j] * (pref ** j) % MOD
        ans = (ans + term) % MOD
    return ans
