def _comb_mod(n: int, k: int) -> int:
    if k < 0 or k > n:
        return 0
    fact = [1] * (n + 1)
    invfact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD
    return fact[n] * invfact[k] * invfact[n - k] % MOD
