def count_beautiful_numbers(l: int, r: int) -> int:
    if l > r:
        return 0
    return _count_up_to(r) - _count_up_to(l - 1)

def _count_up_to(n: int) -> int:
    if n < 1:
        return 0
    digits = str(n)
    dp, need, s_max = _tables(len(digits))
    state = 0
    total = 0
    for pos, ch in enumerate(digits):
        limit = ord(ch) - 48
        nxt = dp[pos + 1]
        for d in range(limit):
            nst = _transition(state, d, s_max)
            if nst >= 0:
                v = nxt.get(nst)
                if v:
                    total += v
        state = _transition(state, limit, s_max)
    return total + _is_beautiful_state(state, need)

def _tables(num_digits: int) -> tuple[list[dict[int, int]], list[tuple[int, int, int, int, bool]], int]:
    if num_digits in _TABLES:
        return _TABLES[num_digits]
    s_max = 9 * num_digits
    need = [(0, 0, 0, 0, False)] + [_factor_exp(s) for s in range(1, s_max + 1)]
    states = [set() for _ in range(num_digits + 1)]
    states[0].add(0)
    for pos in range(num_digits):
        nxt = states[pos + 1]
        for st in states[pos]:
            for d in range(10):
                nst = _transition(st, d, s_max)
                if nst >= 0:
                    nxt.add(nst)
    dp = [None] * (num_digits + 1)
    dp[num_digits] = {st: _is_beautiful_state(st, need) for st in states[num_digits]}
    for pos in range(num_digits - 1, -1, -1):
        nxt = dp[pos + 1]
        get = nxt.get
        cur = {}
        for st in states[pos]:
            total = 0
            for d in range(10):
                nst = _transition(st, d, s_max)
                if nst >= 0:
                    v = get(nst)
                    if v:
                        total += v
            cur[st] = total
        dp[pos] = cur
    _TABLES[num_digits] = (dp, need, s_max)
    return _TABLES[num_digits]

def _factor_exp(n: int) -> tuple[int, int, int, int, bool]:
    a, b, c, d, only_small_primes = 0, 0, 0, 0, True
    while n % 2 == 0:
        n //= 2
        a += 1
    while n % 3 == 0:
        n //= 3
        b += 1
    while n % 5 == 0:
        n //= 5
        c += 1
    while n % 7 == 0:
        n //= 7
        d += 1
    return a, b, c, d, n == 1

def _transition(state: int, d: int, s_max: int) -> int:
    started = (state >> 10) & 1
    s = state >> 11
    if started:
        ns = s + d
        if ns > s_max:
            return -1
        if d == 0 or (state >> 9) & 1:
            return (ns << 11) | (1 << 10) | (1 << 9)
        return ((ns << 11) | (1 << 10) | _NCODE[(state & 1023) * 9 + d - 1])
    if d == 0:
        return 0
    return (d << 11) | (1 << 10) | _NCODE[d - 2]

def _is_beautiful_state(state: int, need: list[tuple[int, int, int, int, bool]]) -> int:
    if not (state >> 10) & 1:
        return 0
    if (state >> 9) & 1:
        return 1
    a, b, c, d, only_small_primes = need[state >> 11]
    if not only_small_primes:
        return 0
    e2, e3, e5, e7 = _decode(state & 1023)
    return 1 if (e2 >= a and e3 >= b and e5 >= c and e7 >= d) else 0

