def max_kagamimochi(n: int, sizes: List[int]) -> int:
    low, high = 0, n

    while low < high:
        mid = (low + high + 1) // 2
        if any(sizes[i] * 2 > sizes[n - mid + i] for i in range(mid)):
            high = mid - 1
        else:
            low = mid

    return low
