def count_beautiful_numbers(l: int, r: int) -> int:
    def is_beautiful(n):
        digits = [int(d) for d in str(n)]
        if sum(digits) == 0:
            return True
        product = math.prod(digits)
        return product % sum(digits) == 0

    return sum(is_beautiful(n) for n in range(l, r + 1))
