def paint_walls(cost: List[int], time: List[int]) -> int:
    n = len(cost)
    INF = 10**30
    dp = [INF] * (n + 1)
    dp[0] = 0

    for c, t in zip(cost, time):
        for j in range(n, 0, -1):
            prev = j - (t + 1)
            if prev < 0:
                prev = 0
            if dp[prev] + c < dp[j]:
                dp[j] = dp[prev] + c
    return dp[n]
