def sum_of_subsequence_powers(nums: List[int], k: int) -> int:
    MOD = 10**9 + 7
    _INV2 = (MOD + 1) // 2
    dp = [0] * (k + 1)
    dp[0] = 1
    for x in nums:
        if x > k:
