def min_swaps_to_group_ones(n: int, s: str) -> int:
    ones = [i - idx for idx, i in enumerate(i for idx, ch in enumerate(s) if ch != '1') if idx < len(s) - 1]
    if not ones:
        return 0
    med = ones[len(ones) // 2]
    return sum(abs(x - med) for x in ones)
