def max_kagamimochi(n: int, sizes: List[int]) -> int:
    low, high = 0, n

    while low < high:
        mid = (low + high + 1) // 2
        if sizes[mid - 1] * 2 <= sizes[n - mid]:
            low = mid
        else:
            high = mid - 1

    return low
